
(function OnePWA() {
  'use strict';

  // ══════════════════════════════════════════════
  // 1. MANIFEST — dynamically inject (single HTML file)
  // ══════════════════════════════════════════════
  const manifest = {
    name: "One Wallet — DeFi Terminal",
    short_name: "One Wallet",
    description: "DeFi Wallet & Trading Terminal",
    start_url: window.location.href,
    display: "standalone",
    orientation: "portrait",
    background_color: "#050508",
    theme_color: "#050508",
    scope: window.location.href,
    icons: [
      {
        src: "data:image/png;base64,",
        sizes: "192x192",
        type: "image/png",
        purpose: "any"
      },
      {
        src: "data:image/png;base64,",
        sizes: "512x512",
        type: "image/png",
        purpose: "any"
      }
    ],
    categories: ["finance", "utilities"],
    shortcuts: [
      { name: "Swap", short_name: "Swap", url: window.location.href + "#swap", description: "Quick Swap" },
      { name: "Portfolio", short_name: "Portfolio", url: window.location.href + "#home", description: "View Portfolio" }
    ]
  };

  const manifestBlob = new Blob([JSON.stringify(manifest)], { type: 'application/manifest+json' });
  const manifestUrl  = URL.createObjectURL(manifestBlob);
  const manifestLink = document.getElementById('one-manifest-link');
  if (manifestLink) manifestLink.href = manifestUrl;

  // ══════════════════════════════════════════════
  // 2. SERVICE WORKER — inline blob (no separate file needed)
  //    Background sync, fetch cache, keep-alive
  // ══════════════════════════════════════════════
  const SW_CODE = `
'use strict';
const CACHE = 'one-v1';
const SYNC_TAG = 'one-bg-sync';

// ── Install: cache self ──
self.addEventListener('install', function(e) {
  self.skipWaiting();
});

// ── Activate: claim all clients ──
self.addEventListener('activate', function(e) {
  e.waitUntil(self.clients.claim());
});

// ── Fetch: cache-first for same-origin, network for APIs ──
self.addEventListener('fetch', function(e) {
  const url = e.request.url;
  // External API calls (price, RPC) — always network
  if (url.includes('api.') || url.includes('rpc.') || url.includes('coingecko') ||
      url.includes('infura') || url.includes('alchemy') || url.includes('moralis')) {
    return; // pass through
  }
  // For CDN scripts — cache first
  if (url.includes('cdnjs') || url.includes('fonts.googleapis') || url.includes('unpkg')) {
    e.respondWith(
      caches.open(CACHE).then(function(cache) {
        return cache.match(e.request).then(function(cached) {
          if (cached) return cached;
          return fetch(e.request).then(function(response) {
            if (response && response.status === 200) {
              cache.put(e.request, response.clone());
            }
            return response;
          }).catch(function() { return cached || new Response('', {status: 503}); });
        });
      })
    );
  }
});

// ── Background Sync — minimize হলেও চলবে ──
self.addEventListener('sync', function(e) {
  if (e.tag === SYNC_TAG || e.tag.startsWith('one-')) {
    e.waitUntil(
      // সব connected clients কে wake up করো
      self.clients.matchAll({ includeUncontrolled: true, type: 'window' }).then(function(clients) {
        clients.forEach(function(client) {
          client.postMessage({ type: 'BG_SYNC', tag: e.tag, ts: Date.now() });
        });
      })
    );
  }
});

// ── Periodic Background Sync (Chrome Android) ──
self.addEventListener('periodicsync', function(e) {
  if (e.tag === 'one-price-sync' || e.tag === 'one-balance-sync') {
    e.waitUntil(
      self.clients.matchAll({ includeUncontrolled: true, type: 'window' }).then(function(clients) {
        clients.forEach(function(client) {
          client.postMessage({ type: 'PERIODIC_SYNC', tag: e.tag, ts: Date.now() });
        });
      })
    );
  }
});

// ── Push Notifications ──
self.addEventListener('push', function(e) {
  const data = e.data ? e.data.json() : { title: 'One Wallet', body: 'Update available' };
  e.waitUntil(
    self.registration.showNotification(data.title || 'One Wallet', {
      body: data.body || '',
      icon: data.icon || '',
      badge: data.badge || '',
      tag: data.tag || 'one',
      data: data,
      vibrate: [200, 100, 200],
      requireInteraction: data.requireInteraction || false
    })
  );
});

// ── Notification Click ──
self.addEventListener('notificationclick', function(e) {
  e.notification.close();
  e.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function(clients) {
      if (clients.length > 0) { clients[0].focus(); return; }
      return self.clients.openWindow(self.registration.scope);
    })
  );
});

// ── Message from main thread ──
self.addEventListener('message', function(e) {
  if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting();
  if (e.data && e.data.type === 'PING') {
    e.ports && e.ports[0] && e.ports[0].postMessage({ type: 'PONG', ts: Date.now() });
  }
});
  `;

  // ══════════════════════════════════════════════
  // 3. REGISTER SERVICE WORKER
  //    Blob URL কাজ করে না — তাই SW কোড localStorage এ
  //    cache করে, তারপর একটা tiny "loader" SW দিয়ে
  //    সেটা fetch করে। Single-file HTML এর একমাত্র
  //    reliable পদ্ধতি।
  // ══════════════════════════════════════════════
  let _swReg = null;

  // SW কোড localStorage এ save করো যাতে loader SW পড়তে পারে
  function _cacheSWCode() {
    try {
      localStorage.setItem('__one_sw_code__', SW_CODE);
      localStorage.setItem('__one_sw_ver__',  '3');
    } catch(e) {}
  }

  // Loader SW — এটা data: URI হিসেবে register করা যায় না,
  // কিন্তু এই trick টা কাজ করে: SW কোড কে একটা
  // same-origin script হিসেবে serve করতে হবে।
  // Single HTML file এ সবচেয়ে ভালো পদ্ধতি:
  // একটা <script> tag inline এ SW code রাখো,
  // তারপর সেই page URL কেই SW হিসেবে register করো
  // "service-worker" query param দিয়ে।
  // Page load এ সেই param detect করে SW context এ run করো।

  const SW_QUERY_PARAM = '__one_sw__';
  const isSWContext = (typeof self !== 'undefined' && typeof importScripts === 'function')
                     || location.search.includes(SW_QUERY_PARAM);

  async function registerSW() {
    if (!('serviceWorker' in navigator)) {
      return;
    }

    // ── Sandboxed / iframe environment detect করো ──
    // claudeusercontent, srcdoc, file://, localhost preview তে SW কাজ করে না
    const _loc = location.href;
    const _isSandboxed = (
      _loc.includes('claudeusercontent') ||
      _loc.includes('srcdoc') ||
      _loc.startsWith('file://') ||
      _loc.includes('127.0.0.1') ||
      _loc.includes('localhost') ||
      window.self !== window.top  // iframe এর ভেতরে
    );

    if (_isSandboxed) {
      // Background Guard + Capacitor BG Engine সব কাজ করবে
      return;
    }

    // SW কোড cache করো
    _cacheSWCode();

    const swUrl = location.pathname + location.search
      + (location.search ? '&' : '?') + SW_QUERY_PARAM + '=1';
      // Note: location.hash is intentionally excluded — hash fragments are never
      // sent to the server so they serve no purpose in a SW registration URL and
      // can cause scope-matching issues in some browsers.

    try {
      _swReg = await navigator.serviceWorker.register(swUrl, {
        scope: location.pathname.replace(/\/[^/]*$/, '/') || '/'
      });

      // Update on new version
      _swReg.addEventListener('updatefound', function() {
        const newSW = _swReg.installing;
        if (newSW) {
          newSW.addEventListener('statechange', function() {
            if (newSW.state === 'installed' && navigator.serviceWorker.controller) {
              newSW.postMessage({ type: 'SKIP_WAITING' });
            }
          });
        }
      });

      // SW message listener
      navigator.serviceWorker.addEventListener('message', function(e) {
        const msg = e.data;
        if (!msg) return;
        if (msg.type === 'BG_SYNC' || msg.type === 'PERIODIC_SYNC') {
          _oneFullRefresh('sw-sync');
        }
      });

      // Periodic background sync
      if (_swReg.periodicSync) {
        try {
          const status = await navigator.permissions.query({ name: 'periodic-background-sync' });
          if (status.state === 'granted') {
            await _swReg.periodicSync.register('one-price-sync',   { minInterval: 60000 });
            await _swReg.periodicSync.register('one-balance-sync', { minInterval: 300000 });
          }
        } catch(e) {}
      }

      // Background sync
      if (_swReg.sync) {
        try { await _swReg.sync.register('one-bg-sync'); } catch(e) {}
      }

    } catch(err) {
      // Silent — production এ কখনো এখানে আসবে না
    }
  }

  // ══════════════════════════════════════════════
  // SW CONTEXT DETECTION
  // এই HTML file টাই SW হিসেবে load হলে
  // SW_CODE execute করো এবং page render skip করো
  // ══════════════════════════════════════════════
  if (typeof location !== 'undefined' && location.search && location.search.includes(SW_QUERY_PARAM)) {
    // আমরা SW context এ আছি — SW_CODE কে execute করো
    // এটা document load এর আগেই inline script এ handle হয়
    // (নিচের <script id="one-sw-bootstrap"> দেখুন)
  }

  // ══════════════════════════════════════════════
  // 4. FULL REFRESH — সব section একসাথে
  // ══════════════════════════════════════════════
  function _oneFullRefresh(source) {

    // Price
    try { if (typeof silentPriceRefresh === 'function') silentPriceRefresh().catch(function(){}); } catch(e) {}

    // Balance + tokens
    try {
      if (typeof _balanceCache !== 'undefined') {
        try {
          const chain = (typeof hwChainId !== 'undefined') ? String(hwChainId) : null;
          if (chain && _balanceCache[chain]) delete _balanceCache[chain];
        } catch(e) {}
      }
      if (typeof loadTokens === 'function' && typeof homeActiveKey !== 'undefined' && homeActiveKey) {
        loadTokens();
      }
    } catch(e) {}

    // Swap DEX scanner
    try {
      if (typeof SW !== 'undefined' && typeof SW._swapActive !== 'undefined' && SW._swapActive) {
        if (SW.scanDexInterval === null && typeof swStartDexScan === 'function') swStartDexScan();
      }
    } catch(e) {}

    // Chart
    try {
      if (typeof _lwChartVisible !== 'undefined' && _lwChartVisible) {
        if      (typeof _lwStartPoll  === 'function') _lwStartPoll();
        else if (typeof lwStartPoll   === 'function') lwStartPoll();
      }
    } catch(e) {}

    // Activity
    try { if (typeof loadActivity === 'function') loadActivity(); } catch(e) {}

    // Portfolio
    try { if (typeof refreshPortfolioStats === 'function') refreshPortfolioStats(); } catch(e) {}

    // Gas
    try { if (typeof refreshGasPrice === 'function') refreshGasPrice(); } catch(e) {}

    // Bridge
    try { if (typeof refreshBridgeQuote === 'function') refreshBridgeQuote(); } catch(e) {}
  }

  // ══════════════════════════════════════════════
  // 5. INSTALL PROMPT — "Add to Home Screen" banner
  // ══════════════════════════════════════════════
  let _deferredInstallPrompt = null;

  window.addEventListener('beforeinstallprompt', function(e) {
    e.preventDefault();
    _deferredInstallPrompt = e;
    _showInstallBanner();
  });

  function _showInstallBanner() {
    // Already installed বা banner already shown থাকলে skip
    if (localStorage.getItem('one-pwa-dismissed') === '1') return;
    if (window.matchMedia('(display-mode: standalone)').matches) return;

    const banner = document.createElement('div');
    banner.id = 'one-install-banner';
    banner.innerHTML = `
      <div style="
        position:fixed; bottom:90px; left:12px; right:12px; z-index:99999;
        background:linear-gradient(135deg,#141423,#0f0f1a);
        border:1px solid rgba(99,102,241,0.4);
        border-radius:18px; padding:14px 16px;
        display:flex; align-items:center; gap:12px;
        box-shadow:0 8px 32px rgba(0,0,0,0.7), 0 0 20px rgba(99,102,241,0.2);
        animation: oneBannerIn 0.4s cubic-bezier(0.34,1.56,0.64,1) both;
      ">
        <div style="width:40px;height:40px;border-radius:12px;background:#050508;border:1px solid rgba(99,102,241,0.3);display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:22px;">⚡</div>
        <div style="flex:1;min-width:0;">
          <div style="color:#f1f1f8;font-size:0.85rem;font-weight:700;font-family:Syne,sans-serif;">Install One Wallet App</div>
          <div style="color:#8b8ba7;font-size:0.72rem;margin-top:2px;">Background এ চলবে • Offline support</div>
        </div>
        <button onclick="window.OnePWA.install()" style="
          background:linear-gradient(135deg,#6366f1,#8b5cf6);
          color:#fff; border:none; border-radius:10px;
          padding:8px 14px; font-size:0.78rem; font-weight:700;
          cursor:pointer; white-space:nowrap; flex-shrink:0;
        ">Install</button>
        <button onclick="window.OnePWA.dismissBanner()" style="
          background:none; border:none; color:#4a4a65;
          cursor:pointer; font-size:18px; padding:4px; flex-shrink:0;
        ">✕</button>
      </div>
      <style>
        @keyframes oneBannerIn {
          from { opacity:0; transform:translateY(20px) scale(0.95); }
          to   { opacity:1; transform:translateY(0) scale(1); }
        }
      </style>
    `;
    document.body.appendChild(banner);
  }

  // iOS Safari install instructions
  function _showIOSInstallHint() {
    const isIOS = /iphone|ipad|ipod/i.test(navigator.userAgent);
    const isStandalone = window.navigator.standalone;
    if (!isIOS || isStandalone) return;
    if (localStorage.getItem('one-pwa-dismissed') === '1') return;

    setTimeout(function() {
      const hint = document.createElement('div');
      hint.innerHTML = `
        <div style="
          position:fixed; bottom:90px; left:12px; right:12px; z-index:99999;
          background:linear-gradient(135deg,#141423,#0f0f1a);
          border:1px solid rgba(99,102,241,0.4);
          border-radius:18px; padding:16px;
          box-shadow:0 8px 32px rgba(0,0,0,0.7);
          text-align:center;
        ">
          <div style="color:#f1f1f8;font-size:0.85rem;font-weight:700;margin-bottom:8px;">📲 Install One Wallet</div>
          <div style="color:#8b8ba7;font-size:0.75rem;line-height:1.5;">
            Safari এ <strong style="color:#6366f1;">Share ↑</strong> বাটন চাপুন<br>
            তারপর <strong style="color:#6366f1;">"Add to Home Screen"</strong> সিলেক্ট করুন
          </div>
          <button onclick="this.closest('div').parentElement.remove();localStorage.setItem('one-pwa-dismissed','1')" style="
            margin-top:12px; background:rgba(99,102,241,0.15);
            color:#6366f1; border:1px solid rgba(99,102,241,0.3);
            border-radius:8px; padding:7px 20px; font-size:0.78rem; cursor:pointer;
          ">Got it</button>
        </div>
      `;
      document.body.appendChild(hint);
    }, 4000);
  }

  // ══════════════════════════════════════════════
  // 6. PUBLIC API
  // ══════════════════════════════════════════════
  window.OnePWA = {
    install: async function() {
      if (_deferredInstallPrompt) {
        _deferredInstallPrompt.prompt();
        const result = await _deferredInstallPrompt.userChoice;
        _deferredInstallPrompt = null;
        const banner = document.getElementById('one-install-banner');
        if (banner) banner.remove();
        if (result.outcome === 'accepted') {
          localStorage.setItem('one-pwa-dismissed', '1');
        }
      }
    },
    dismissBanner: function() {
      const banner = document.getElementById('one-install-banner');
      if (banner) banner.remove();
      localStorage.setItem('one-pwa-dismissed', '1');
    },
    refresh: _oneFullRefresh,
    getRegistration: function() { return _swReg; },
    isInstalled: function() {
      return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone;
    },
    isOnline: function() { return navigator.onLine; }
  };

  // ══════════════════════════════════════════════
  // 7. ONLINE / OFFLINE HANDLING
  // ══════════════════════════════════════════════
  window.addEventListener('online', function() {
    setTimeout(function() { _oneFullRefresh('online'); }, 1000);
  });

  window.addEventListener('offline', function() {
    // Offline indicator যোগ করো
    _showOfflineBadge();
  });

  function _showOfflineBadge() {
    let badge = document.getElementById('one-offline-badge');
    if (!badge) {
      badge = document.createElement('div');
      badge.id = 'one-offline-badge';
      badge.innerHTML = `<div style="
        position:fixed; top:12px; left:50%; transform:translateX(-50%);
        z-index:99999; background:#f43f5e; color:#fff;
        padding:5px 16px; border-radius:20px; font-size:0.72rem; font-weight:700;
        box-shadow:0 4px 12px rgba(244,63,94,0.4);
      ">⚠ Offline</div>`;
      document.body.appendChild(badge);
    }
    window.addEventListener('online', function removeBadge() {
      badge.remove();
      window.removeEventListener('online', removeBadge);
    }, { once: true });
  }

  // ══════════════════════════════════════════════
  // 8. BOOT SEQUENCE
  // ══════════════════════════════════════════════
  window.addEventListener('load', function() {
    // SW register করো
    registerSW();
    // iOS hint
    _showIOSInstallHint();
    // Installed হলে সাথে সাথে refresh
    if (window.OnePWA.isInstalled()) {
      setTimeout(function() { _oneFullRefresh('pwa-launch'); }, 1500);
    }
  });

  // App installed event
  window.addEventListener('appinstalled', function() {
    localStorage.setItem('one-pwa-dismissed', '1');
    const banner = document.getElementById('one-install-banner');
    if (banner) banner.remove();
  });

})();
